import asyncio
import json
from typing import Any
import httpx
from fastmcp.server import FastMCP


async def create_openapi_mcp_server(
    spec: dict[str, Any],
    client: httpx.AsyncClient,
    server_name: str = "OpenAPI MCP Server",
) -> FastMCP:
    """
    Generate an MCP server from an OpenAPI 3.0 specification.

    Args:
        spec: OpenAPI 3.0 specification as a Python dict
        client: Configured httpx.AsyncClient with base URL set
        server_name: Name for the MCP server

    Returns:
        FastMCP server instance with tools mirroring OpenAPI operations
    """
    server = FastMCP(name=server_name)

    paths = spec.get("paths", {})
    base_url = str(client.base_url) if client.base_url else ""

    for path, path_item in paths.items():
        for method, operation in path_item.items():
            if method.lower() not in ("get", "post", "put", "patch", "delete", "head", "options"):
                continue

            operation_id = operation.get("operationId", f"{method.upper()}_{path.replace('/', '_')}")
            description = operation.get("description", operation.get("summary", ""))
            parameters = operation.get("parameters", [])
            request_body = operation.get("requestBody")

            param_schema = {"type": "object", "properties": {}, "required": []}

            for param in parameters:
                param_name = param.get("name")
                param_schema_def = param.get("schema", {"type": "string"})
                param_schema["properties"][param_name] = param_schema_def

                if param.get("required", False):
                    param_schema["required"].append(param_name)

            if request_body:
                content = request_body.get("content", {})
                json_content = content.get("application/json", {})
                body_schema = json_content.get("schema", {"type": "object"})
                param_schema["properties"]["_body"] = body_schema

                if request_body.get("required", False):
                    param_schema["required"].append("_body")

            async def make_tool(
                method_upper: str,
                path_str: str,
                base_url_str: str,
                client_ref: httpx.AsyncClient,
            ):
                async def tool_func(**kwargs) -> str:
                    url = f"{base_url_str}{path_str}"

                    query_params = {}
                    headers = {}
                    body_data = None

                    for key, value in kwargs.items():
                        if key == "_body":
                            body_data = value
                        elif key.startswith("header_"):
                            header_name = key.replace("header_", "")
                            headers[header_name] = value
                        else:
                            query_params[key] = value

                    try:
                        if method_upper == "GET":
                            resp = await client_ref.get(url, params=query_params, headers=headers)
                        elif method_upper == "POST":
                            resp = await client_ref.post(
                                url, params=query_params, json=body_data, headers=headers
                            )
                        elif method_upper == "PUT":
                            resp = await client_ref.put(
                                url, params=query_params, json=body_data, headers=headers
                            )
                        elif method_upper == "PATCH":
                            resp = await client_ref.patch(
                                url, params=query_params, json=body_data, headers=headers
                            )
                        elif method_upper == "DELETE":
                            resp = await client_ref.delete(url, params=query_params, headers=headers)
                        else:
                            return f"Unsupported HTTP method: {method_upper}"

                        return json.dumps(
                            {
                                "status_code": resp.status_code,
                                "headers": dict(resp.headers),
                                "body": resp.json() if resp.headers.get("content-type", "").startswith("application/json") else resp.text,
                            }
                        )
                    except Exception as e:
                        return json.dumps({"error": str(e), "type": type(e).__name__})

                return tool_func

            tool_func = await make_tool(method.upper(), path, base_url, client)
            server.add_tool(
                name=operation_id,
                description=description or f"{method.upper()} {path}",
                func=tool_func,
                input_schema=param_schema if param_schema["properties"] else {"type": "object"},
            )

    return server


if __name__ == "__main__":

    spec = {
